head.script:
requires("uiplugin.popup");
scwin.trigger1_onclick = function(e) {
	var options = {
		type: "wframePopup",
		id: "testpopup",
		modal: true,
		useHeadingTagTitle: true
	};
	$p.openPopup("/sample/common_link/p_wframePopup_layerpopup_WESD-1289_(WSQ-5269)_main_popup.xml", options);
};
scwin.trigger2_onclick = function(e) {
	$p.openPopup("/sample/common_link/p_wframePopup_layerpopup_WESD-1289_(WSQ-5269)_main_popup.xml", { type: "wframePopup", id: "testpopup2", modal: false, top: "300px" });
};
scwin.checkVal = function() {
	return document.getElementById('mf_testpopup_header').getElementsByTagName('h2').length == 1;
};
